import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import {
  Tab as AriaTab,
  TabList as AriaTabList,
  TabPanel as AriaTabPanel,
  type TabPanelProps as AriaTabPanelProps,
  type TabProps as AriaTabProps,
  Tabs as AriaTabs,
  type TabsProps as AriaTabsProps,
  composeRenderProps,
} from "react-aria-components";
import { cn } from "./utils";

export interface TabsProps extends AriaTabsProps {
  defaultValue?: string;
  value?: string;
  onValueChange?: (value: string) => void;
}

export function Tabs({
  className,
  defaultValue,
  value,
  onValueChange,
  ...props
}: TabsProps) {
  return (
    <AriaTabs
      {...props}
      {...(defaultValue !== undefined && { defaultSelectedKey: defaultValue })}
      {...(value !== undefined && { selectedKey: value })}
      onSelectionChange={(key) => {
        props.onSelectionChange?.(key);
        onValueChange?.(String(key));
      }}
      data-slot="tabs"
      className={composeRenderProps(className, (className) =>
        cn("w-full", className),
      )}
    />
  );
}

export function TabList({
  className,
  ...props
}: React.ComponentProps<typeof AriaTabList>) {
  return (
    <AriaTabList
      {...props}
      data-slot="tabs-list"
      className={composeRenderProps(className, (className) =>
        cn(
          "inline-flex max-w-full gap-1.5 overflow-x-auto rounded-xl bg-muted p-1.5 shadow-[var(--shadow-inset)] ring-1 ring-border/70",
          className,
        ),
      )}
    />
  );
}

export function Tab({ className, ...props }: AriaTabProps) {
  return (
    <AriaTab
      {...props}
      data-slot="tabs-trigger"
      className={composeRenderProps(className, (className) =>
        cn(
          "min-h-11 cursor-pointer whitespace-nowrap sm:min-h-9 rounded-lg px-4 py-2 text-[13px] font-medium text-muted-foreground outline-none hover:bg-card/70 data-[selected]:bg-card data-[selected]:text-foreground data-[selected]:shadow-[var(--shadow-card)] data-[selected]:ring-1 data-[selected]:ring-border/70 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring data-[disabled]:cursor-default data-[disabled]:opacity-50 motion-safe:transition-[background-color,color,box-shadow,scale] motion-safe:duration-150 motion-safe:active:scale-[0.96]",
          className,
        ),
      )}
    />
  );
}

export function TabPanel({ className, ...props }: AriaTabPanelProps) {
  return (
    <AriaTabPanel
      {...props}
      data-slot="tabs-content"
      className={composeRenderProps(className, (className) =>
        cn(
          "mt-5 rounded-xl bg-card p-5 text-sm leading-6 text-foreground shadow-[var(--shadow-card)] ring-1 ring-border/70 outline-none data-[focus-visible]:shadow-[inset_3px_0_0_var(--ring)] forced-colors:data-[focus-visible]:outline-2 forced-colors:data-[focus-visible]:outline-solid forced-colors:data-[focus-visible]:-outline-offset-2 forced-colors:data-[focus-visible]:outline-[Highlight]",
          className,
        ),
      )}
    />
  );
}

export const TabsList = TabList;
export function TabsTrigger({
  value,
  ...props
}: Omit<AriaTabProps, "id"> & { id?: AriaTabProps["id"]; value?: string }) {
  return <Tab {...props} id={value ?? props.id} />;
}

export function TabsContent({
  value,
  ...props
}: Omit<AriaTabPanelProps, "id"> & {
  id?: AriaTabPanelProps["id"];
  value?: string;
}) {
  return <TabPanel {...props} id={value ?? props.id} />;
}

import type { HTMLAttributes } from "react";
import { tv, type VariantProps } from "tailwind-variants";
import { cn } from "./utils";

const badgeStyles = tv({
  base: "inline-flex min-h-7 items-center gap-1.5 rounded-full px-3 py-1 text-xs font-medium leading-4 tracking-normal shadow-[var(--shadow-card)] ring-1",
  variants: {
    variant: {
      neutral: "bg-secondary text-secondary-foreground ring-border",
      accent: "bg-accent text-accent-foreground ring-primary/15",
      success: "bg-success-subtle text-success-foreground ring-success/15",
      warning: "bg-warning-subtle text-warning-foreground ring-warning/20",
      error: "bg-card text-destructive ring-destructive/25",
      outline: "bg-transparent text-foreground ring-border",
    },
  },
  defaultVariants: { variant: "neutral" },
});

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: NonNullable<VariantProps<typeof badgeStyles>["variant"]>;
  dot?: boolean;
}

export function Badge({
  variant = "neutral",
  dot = false,
  className,
  children,
  ...props
}: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-variant={variant}
      className={badgeStyles({ variant, className })}
      {...props}
    >
      {dot && <BadgeDot />}
      {children}
    </span>
  );
}

export function BadgeDot({
  className,
  ...props
}: HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      aria-hidden="true"
      {...props}
      data-slot="badge-dot"
      className={cn("size-1.5 rounded-full bg-current", className)}
    />
  );
}
